def link_existing_disposals(apps, schema_editor):
    """
    Link each disposal to the screening that caused it:
    - a 'Ver: V123' reference left in Notes by the old form, if it is for the same unit
    - otherwise, for 'Failed Verification' disposals, the latest failed screening of that unit
    """
    Disposal = apps.get_model('bloodbank', 'Disposal')
    Verification = apps.get_model('bloodbank', 'Verification')
    for d in Disposal.objects.filter(verification__isnull=True):
        match = re.search(r'Ver:\s*([A-Za-z0-9_-]+)', d.Notes or '')
        ver = None
        if match:
            ver = Verification.objects.filter(pk=match.group(1).upper(), unit_id=d.unit_id).first()
        if ver is None and d.Reason == 'Failed Verification':
            ver = Verification.objects.filter(unit_id=d.unit_id, OverallResult='Failed').order_by('-Date').first()
        if ver is not None:
            d.verification_id = ver.pk
            d.save(update_fields=['verification'])


